<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">    .</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">newInstanceSpecial</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">(exampleClass)</span></span>
